function subarraySum(nums, k) {
  const seen = new Map([[0, 1]]) // running total -> how many times seen
  let running = 0
  let count = 0
  for (const x of nums) {
    running += x
    count += seen.get(running - k) ?? 0 // earlier totals that leave exactly k
    seen.set(running, (seen.get(running) ?? 0) + 1)
  }
  return count
}

