function applyIncrements(n, updates) {
  const diff = new Array(n + 1).fill(0)
  for (const [start, end, delta] of updates) {
    diff[start] += delta // the change begins here
    diff[end + 1] -= delta // and stops after end
  }
  const out = []
  let running = 0
  for (let i = 0; i < n; i++) {
    running += diff[i]
    out.push(running)
  }
  return out
}

