function regionSums(matrix, queries) {
  const rows = matrix.length
  const cols = matrix[0].length
  // P[r][c] = sum of the block above and left of (r, c), exclusive; row 0 and column 0 stay 0
  const P = Array.from({ length: rows + 1 }, () => new Array(cols + 1).fill(0))
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      P[r + 1][c + 1] = matrix[r][c] + P[r][c + 1] + P[r + 1][c] - P[r][c]
    }
  }
  return queries.map(([r1, c1, r2, c2]) => P[r2 + 1][c2 + 1] - P[r1][c2 + 1] - P[r2 + 1][c1] + P[r1][c1])
}

solution.python:
def region_sums(matrix, queries):
    rows, cols = len(matrix), len(matrix[0])
    # P[r][c] = sum of the block above and left of (r, c), exclusive; row 0 and column 0 stay 0
    P = [[0] * (cols + 1) for _ in range(rows + 1)]
    for r in range(rows):
        for c in range(cols):
            P[r + 1][c + 1] = matrix[r][c] + P[r][c + 1] + P[r + 1][c] - P[r][c]
    return [P[r2 + 1][c2 + 1] - P[r1][c2 + 1] - P[r2 + 1][c1] + P[r1][c1]
            for r1, c1, r2, c2 in queries]

