def rotate_image(matrix):
    n = len(matrix)
    for r in range(n):
        for c in range(r + 1, n):               # only above the diagonal, or you swap twice
            matrix[r][c], matrix[c][r] = matrix[c][r], matrix[r][c]
    for row in matrix:
        row.reverse()                           # mirror left to right
    return matrix

